import heapq


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            choices.append([-1] + versions)

        best_vector = None
        best = None
        roots = data["roots"]
        for values in product(*choices):
            selected = {name: version for name, version in zip(names, values)
                        if version != -1}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            rows = {}
            for name, version in selected.items():
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)
            edges = {name: [] for name in selected}
            valid = True
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if (target not in selected or
                            not dep["min"] <= selected[target] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(selected):
                continue

            active, finished = set(), set()
            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(dep) for dep in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in selected):
                continue

            vector = tuple(selected.get(name, -1) for name in names)
            if (best_vector is None or
                    (vector > best_vector if preference == "maximum"
                     else vector < best_vector)):
                best_vector = vector
                best = selected
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


